package com.dudlatitat.nextchapter.data

/**
 * Exam-style A+ questions, written for this app from CompTIA's public exam objectives (Core 1
 * 220-1201, Core 2 220-1202). Unlike the study cards, these are mostly scenarios ("a user
 * reports…, what should the technician do FIRST?") with wrong options that are wrong for a
 * reason, some "choose two", and some "put the steps in order". Every question explains why.
 * Ids: "x1:" Core 1, "x2:" Core 2. Pure, checked in ExamBankTest.
 */
object ExamBank {
    enum class Kind { SINGLE, MULTI, ORDER }

    /**
     * One question. For SINGLE/MULTI, [right] are the correct options and [wrong] the others.
     * For ORDER, [right] holds the steps in their correct order and [wrong] is empty.
     */
    data class Q(
        val id: String, val core: Int, val domain: Int, val kind: Kind,
        val stem: String, val right: List<String>, val wrong: List<String>, val why: String,
    ) {
        val options: List<String> get() = right + wrong
    }

    private fun s(core: Int, d: Int, key: String, stem: String, right: String, w1: String, w2: String, w3: String, why: String) =
        Q("x$core:$key", core, d, Kind.SINGLE, stem, listOf(right), listOf(w1, w2, w3), why)

    private fun m(core: Int, d: Int, key: String, stem: String, right: List<String>, wrong: List<String>, why: String) =
        Q("x$core:$key", core, d, Kind.MULTI, stem, right, wrong, why)

    private fun o(core: Int, d: Int, key: String, stem: String, steps: List<String>, why: String) =
        Q("x$core:$key", core, d, Kind.ORDER, stem, steps, emptyList(), why)

